/// One tinted label swatch: a fill, ink that clears 4.5:1 on that fill, and a hairline.
class PxTag {
  const PxTag(this.name, this.bg, this.ink, this.border);
  final String name;
  final Color bg;
  final Color ink;
  final Color border;
}

