/// Picks a stable swatch for a piece of text — a sender, a label, a tenant — so the
/// same name is always the same colour, without storing a colour per record.
PxTag pxTagFor(String seed, {required bool dark}) {
  final palette = dark ? pxTagDark : pxTagLight;
  var hash = 0;
  for (final unit in seed.codeUnits) {
    hash = (hash * 31 + unit) & 0x1fffffff;
  }
  // Skips index 0, the neutral swatch, which is reserved for 'no category'.
  return palette[1 + hash % (palette.length - 1)];
}
